VOICE_ID = ([(a, 'कर्तृवाच्य') for a, b in VOICE[:8]] + [(b, 'कर्मवाच्य') for a, b in VOICE]
            + [(b, 'भाववाच्य') for a, b in BHAV] + [(a, 'कर्तृवाच्य') for a, b in BHAV[:6]])
VOICE_EXPL = {'कर्तृवाच्य': 'क्रिया कर्ता के अनुसार है और कर्ता प्रधान है।',
              'कर्मवाच्य': 'कर्म प्रधान है; कर्ता ‘द्वारा’/‘से’ के साथ आता है और क्रिया कर्म के लिंग-वचन के अनुसार है (‘किया गया’, ‘की जाएगी’)।',
              'भाववाच्य': 'न कर्ता प्रधान है न कर्म; क्रिया का भाव प्रधान है — क्रिया सदा पुल्लिंग, एकवचन, अन्य पुरुष (‘सोया नहीं जाता’)।'}


def g_voice(kit, key, th):
    def ident(rng, slot):
        s, v = rng.choice(VOICE_ID)
        w = [x for x in ('कर्तृवाच्य', 'कर्मवाच्य', 'भाववाच्य') if x != v] + ['मिश्र वाक्य']
        return mcq(rng, f'निम्नलिखित वाक्य में कौन-सा वाच्य है?\n“{s}”', v, w, f'{v}: {VOICE_EXPL[v]}')
    kit.add(key, 'C1', (1, 3), ident, 'mcq', 'p2r', 'voice_id')

    def why(rng, slot):
        a, b = rng.choice(VOICE)
        return dict(stem=f'समाचार रिपोर्ट में “{a}” के स्थान पर “{b}” लिखा गया। औपचारिक लेखन में कर्मवाच्य के ऐसे प्रयोग के दो लाभ बताइए।',
                    answer='ध्यान कर्ता से हटकर कार्य/घटना पर केंद्रित होता है; भाषा निर्वैयक्तिक, औपचारिक और वस्तुनिष्ठ लगती है; कर्ता अज्ञात या कम महत्त्वपूर्ण हो तो उसे छोड़ा जा सकता है।',
                    type='explain', marks=2, markingKey='प्रत्येक उचित लाभ के लिए 1 अंक (कार्य पर ध्यान, औपचारिकता/निष्पक्षता, कर्ता का लोप)।')
    kit.add(key, 'C2', (1, 4), why, 'explain', None, 'voice_why')

    def bhav(rng, slot):
        a, b = rng.choice(BHAV)
        if rng.random() < 0.5:
            return dict(stem=f'निम्नलिखित वाक्य को भाववाच्य में बदलिए:\n“{a}”', answer=b, type='short', marks=2,
                        markingKey=f'{b} — 1 अंक: कर्ता के साथ ‘से’; 1 अंक: क्रिया का भाववाच्य रूप (पुल्लिंग, एकवचन — ‘…या जाता/गया’)।')
        return dict(stem=f'भाववाच्य वाक्य “{b}” को कर्तृवाच्य में बदलिए।', answer=a, type='short', marks=2,
                    markingKey=f'{a} — 1 अंक: कर्ता प्रधान (बिना ‘से’); 1 अंक: क्रिया का कर्ता के अनुसार रूप (‘पाना/सकना’ सहित)।')
    kit.add(key, 'C3', (2, 4), bhav, 'short', None, 'voice_bhav')

    def choose(rng, slot):
        a, b = rng.choice(VOICE)
        oth = [x[1] for x in VOICE if x[1] != b]
        wrong = [b.replace(' गया।', ' गई।') if ' गया।' in b else b.replace(' गई।', ' गया।') if ' गई।' in b else b.replace('जाएगी', 'जाएगा') if 'जाएगी' in b else b.replace('जाएगा', 'जाएगी'),
                 a.replace('ने ', 'द्वारा ', 1), b.replace(' द्वारा', ' ने', 1)]
        wrong = [w for w in dict.fromkeys(wrong) if w != b]
        if len(wrong) < 3:
            wrong += rng.sample(oth, 3 - len(wrong))
        return mcq(rng, f'वाक्य “{a}” का शुद्ध कर्मवाच्य रूप कौन-सा है?', b, wrong[:3], f'शुद्ध रूप: {b} ({VOICE_EXPL["कर्मवाच्य"]})')
    kit.add(key, 'C2', (2, 4), choose, 'mcq', None, 'voice_mcq')


