# --------------------------------------------------------------------------------------------
# Excerpts: year 2 questions often point at several sentences (openings, titles, contrasts). Pick the
# shortest window (3–5 sentences) that holds every quoted phrase and most of the question/answer words,
# so the excerpt shown in the stem always contains what the answer relies on. Used only when this pack
# is loaded (the engine builds one subject per run).
# --------------------------------------------------------------------------------------------
def _excerpt12(body, probe, width=3):
    import re
    parts = [x.strip() for x in re.split(r'(?<=[।?!])\s+|\n', body) if x.strip()]
    if len(parts) <= width:
        return body
    quotes = [q.strip('…. ').split('…')[0].strip() for q in re.findall(r'[“‘"]([^”’"]{3,})[”’"]', probe)]
    quotes = [q for q in quotes if q and q in body]
    pt = H._toks(probe) & H._toks(body)
    best = None
    for w in (3, 4, 5):
        if w > len(parts):
            break
        for lo in range(0, len(parts) - w + 1):
            seg = ' '.join(parts[lo:lo + w])
            qok = all(q in seg for q in quotes)
            cov = len(H._toks(seg) & pt) / max(1, len(pt))
            score = (qok, cov >= 0.75, cov, -w, -lo)
            if best is None or score > best[0]:
                best = (score, seg)
        if best[0][0] and best[0][1]:
            break
    if not best[0][0] or best[0][2] < 0.6:  # the question needs the whole text
        return body
    return best[1]


H.excerpt = _excerpt12


