def g_cond(kit, key, th):
    def ident(rng, slot):
        r, u, f = rng.choice(COND)
        others = [x[0] for x in COND if x[0] != r]
        return mcq(rng, 'निम्नलिखित में से किस वाक्य से पता चलता है कि शर्त वास्तव में पूरी नहीं हुई (काल्पनिक/असंभाव्य शर्त)?', u, rng.sample(others, 3),
                   f'‘{u}’ — अपूर्ण कृदंत रूप (…ते/…ती) दिखाता है कि शर्त पूरी नहीं हुई: {f}')
    kit.add(key, 'C1', (1, 3), ident, 'mcq', 'p2r', 'cond_id')

    def meaning(rng, slot):
        r, u, f = rng.choice(COND)
        w = ['शर्त पूरी हुई और उसका परिणाम भी मिला।', 'यह भविष्य की एक संभावना है जो अभी पूरी हो सकती है।', 'यह किसी व्यक्ति को दिया गया आदेश है।']
        return mcq(rng, f'वाक्य “{u}” का वास्तविक अर्थ क्या है?', f, w, f'काल्पनिक शर्तवाचक वाक्य बताता है कि वास्तव में ऐसा नहीं हुआ: {f}')
    kit.add(key, 'C2', (2, 4), meaning, 'mcq', None, 'cond_mean')

    def clause(rng, slot):
        r, u, f = rng.choice(COND)
        a, b = r.split(', तो ')
        a2, b2 = u.split(', तो ')
        oth = [x for x in COND if x[0] != r]
        o1, o2 = rng.sample(oth, 2)
        w = [b2.rstrip('।'), o1[1].split(', तो ')[1].rstrip('।'), o2[1].split(', तो ')[1].rstrip('।')]
        return mcq(rng, f'वाक्य पूरा कीजिए (संभाव्य शर्त — भविष्य में ऐसा हो सकता है):\n“{a}, तो ____।”', b.rstrip('।'), w,
                   f'संभाव्य शर्त में ‘अगर/यदि … -एगा/-ओगे’ के साथ परिणाम भी भविष्यत् काल में: “{r}”')
    kit.add(key, 'C2', (1, 3), clause, 'mcq', None, 'cond_clause')

    def explain(rng, slot):
        r, u, f = rng.choice(COND)
        return dict(stem=f'इन दो वाक्यों के अर्थ में क्या अंतर है? स्पष्ट कीजिए।\n(क) {r}\n(ख) {u}',
                    answer=f'(क) संभाव्य शर्त — भविष्य में शर्त पूरी हो सकती है, परिणाम संभव है। (ख) काल्पनिक शर्त — शर्त पूरी नहीं हुई, इसलिए परिणाम भी नहीं मिला: {f}',
                    type='explain', marks=2, markingKey='1 अंक: (क) को संभाव्य/भविष्य की संभावना बताना; 1 अंक: (ख) को अपूर्ण/काल्पनिक शर्त बताकर वास्तविक स्थिति लिखना।')
    kit.add(key, 'C2', (2, 4), explain, 'explain', None, 'cond_expl')

    def fact(rng, slot):
        r, u, f = rng.choice(COND)
        return dict(stem=f'इस वास्तविक स्थिति को ‘अगर/यदि … तो’ वाले काल्पनिक शर्तवाचक वाक्य में बदलिए, जिससे पछतावा या कल्पना व्यक्त हो:\n“{f}”',
                    answer=u, type='short', marks=2, markingKey=f'{u} — 1 अंक: ‘अगर/यदि … तो’ संरचना; 1 अंक: दोनों उपवाक्यों में अपूर्ण कृदंत (…ते/…ती) का सही प्रयोग।')
    kit.add(key, 'C3', (2, 4), fact, 'short', None, 'cond_fact')


