ALANK_NAMES = ['अनुप्रास', 'यमक', 'श्लेष', 'उपमा', 'रूपक', 'उत्प्रेक्षा', 'मानवीकरण', 'अतिशयोक्ति']


def g_dohe(kit, key, th):
    def poet(rng, slot):
        d, p, b, k = rng.choice(DOHE)
        return mcq(rng, f'यह दोहा पढ़िए:\n“{d}”\nयह दोहा किस कवि का है?', p, rng.sample([x for x in POETS if x != p], 3),
                   f'यह {p} का दोहा है। भाव: {b}')
    kit.add(key, 'C1', (1, 2), poet, 'mcq', None, 'doha_poet')

    def bhav(rng, slot):
        d, p, b, k = rng.choice(DOHE)
        others = [x[2] for x in DOHE if x[0] != d]
        return mcq(rng, f'{p} के इस दोहे का भाव (मूल संदेश) कौन-सा विकल्प सही बताता है?\n“{d}”', b, rng.sample(others, 3), b)
    kit.add(key, ('C1', 'C2'), (2, 3), bhav, 'mcq', 'p2r', 'doha_bhav')

    def both(rng, slot):
        d, p, b, k = rng.choice(DOHE)
        return dict(stem=f'{p} का दोहा:\n“{d}”\nइस दोहे का भाव-पक्ष और कला-पक्ष, दोनों संक्षेप में स्पष्ट कीजिए।',
                    answer=f'भाव-पक्ष: {b} कला-पक्ष: {k}', type='explain', marks=4,
                    markingKey=f'2 अंक भाव-पक्ष ({b}); 2 अंक कला-पक्ष — कम से कम दो शिल्पगत विशेषताएँ ({k})।')
    kit.add(key, 'C2', (2, 4), both, 'explain', None, 'doha_both')

    def today(rng, slot):
        d, p, b, k = rng.choice(DOHE)
        m = 6 if slot.d >= 4 else 4
        return dict(stem=f'“{d}” — {p}\nक्या इस दोहे की सीख आज के किशोर जीवन (विद्यालय, परिवार या सोशल मीडिया) में प्रासंगिक है? एक ठोस उदाहरण के साथ 100–120 शब्दों में लिखिए।',
                    answer=f'दोहे का भाव: {b} अपेक्षित: भाव की सही समझ, आज के जीवन से एक ठोस उदाहरण, स्पष्ट मत।', type='explain', marks=m,
                    markingKey=f'{m} अंक: दोहे के भाव की सही व्याख्या (1–2), आज के संदर्भ से ठोस उदाहरण (1–2), तर्कसंगत मत (1), सुसंगत भाषा (1)।')
    kit.add(key, 'C4', (3, 5), today, 'explain', None, 'doha_today')

    def pair(rng, slot):
        a, b = rng.sample(DOHE, 2)
        return dict(stem=f'इन दो दोहों की तुलना कीजिए:\n(क) “{a[0]}” — {a[1]}\n(ख) “{b[0]}” — {b[1]}\nदोनों के संदेश में क्या समानता या अंतर है? 60–80 शब्दों में लिखिए।',
                    answer=f'(क) का भाव: {a[2]} (ख) का भाव: {b[2]} दोनों नैतिक जीवन-मूल्य सरल दृष्टांतों से समझाते हैं; अंतर विषय के स्तर पर।', type='short', marks=4,
                    markingKey='1 अंक प्रत्येक दोहे के भाव की सही समझ (2); 1 अंक समानता/अंतर की स्पष्ट पहचान; 1 अंक तुलना की भाषा (‘जबकि’, ‘दोनों में’, ‘इसके विपरीत’)।')
    kit.add(key, 'C3', (3, 5), pair, 'short', None, 'doha_pair')

    def al_id(rng, slot):
        l, a, e = rng.choice(ALANK)
        return mcq(rng, f'काव्य-पंक्ति: “{l}”\nइस पंक्ति में मुख्य रूप से कौन-सा अलंकार है?', a, rng.sample([x for x in ALANK_NAMES if x != a], 3), e)
    kit.add(key, 'C1', (1, 3), al_id, 'mcq', None, 'alank_id')

    def al_ex(rng, slot):
        l, a, e = rng.choice(ALANK)
        return dict(stem=f'“{l}”\nइस पंक्ति में ‘{a}’ अलंकार कैसे है, स्पष्ट कीजिए और बताइए कि इससे पंक्ति के सौंदर्य या प्रभाव में क्या वृद्धि होती है।',
                    answer=e, type='explain', marks=2, markingKey=f'1 अंक: अलंकार का आधार सही बताना — {e}; 1 अंक: प्रभाव (ध्वनि-सौंदर्य, चित्रात्मकता या भाव की तीव्रता)।')
    kit.add(key, 'C2', (2, 4), al_ex, 'explain', None, 'alank_ex')


