def g_drama(kit, key, th):
    def ident(rng, slot):
        l, d, e = rng.choice(DRAMA_LINES)
        return mcq(rng, f'नाटक का अंश:\n“{l}”\nइस अंश में नाट्य-शिल्प की कौन-सी युक्ति प्रमुख है?', d,
                   rng.sample([x for x in DRAMA_NAMES if x != d], 3), e)
    kit.add(key, 'C1', (1, 3), ident, 'mcq', None, 'dr_id')

    def effect(rng, slot):
        l, d, e = rng.choice(DRAMA_LINES)
        return dict(stem=f'“{l}”\nइस अंश में ‘{d}’ का प्रयोग दर्शकों पर क्या प्रभाव डालता है? मंचन की दृष्टि से समझाइए।', answer=e, type='explain', marks=3,
                    markingKey=f'1 अंक: युक्ति की पहचान और अंश में उसका स्थान; 2 अंक: दर्शकों पर प्रभाव — {e}')
    kit.add(key, 'C2', (2, 4), effect, 'explain', None, 'dr_eff')

    SCENES = [('एक परीक्षा-परिणाम वाले दिन पिता और बेटी की बातचीत', 'निराशा और फिर समझ'),
              ('एक गाँव में पानी के लिए दो पड़ोसियों का झगड़ा', 'क्रोध से समझौते तक'),
              ('रेलवे प्लेटफ़ॉर्म पर बिछड़ते दो पुराने मित्र', 'विदा का दुख'),
              ('दफ़्तर में रिश्वत लेने से मना करता एक युवा कर्मचारी', 'नैतिक द्वंद्व'),
              ('अस्पताल के बाहर प्रतीक्षा करता एक परिवार', 'चिंता और आशा')]

    def write(rng, slot):
        s, mood = rng.choice(SCENES)
        return dict(stem=f'‘{s}’ — इस स्थिति पर 8–10 संवादों का एक छोटा नाट्य-दृश्य लिखिए। उसमें कम से कम दो रंग-निर्देश और एक स्वगत कथन हो, और भाव-परिवर्तन ({mood}) स्पष्ट दिखे।',
                    answer='अपेक्षित: पात्रों के नाम सहित संवाद; कोष्ठक में मंच/अभिनय के रंग-निर्देश; एक स्वगत कथन; संवादों से भाव-परिवर्तन; स्वाभाविक बोलचाल की भाषा।', type='long', marks=8,
                    markingKey='8 अंक: नाट्य-प्रारूप (नाम, संवाद) (2), दो सार्थक रंग-निर्देश (2), स्वगत कथन (1), भाव-परिवर्तन और द्वंद्व (2), भाषा (1)।')
    kit.add(key, 'C4', (3, 5), write, 'long', None, 'dr_write')

    def stage(rng, slot):
        l, d, e = rng.choice([x for x in DRAMA_LINES if x[1] not in ('रंग-निर्देश',)])
        return dict(stem=f'आप इस अंश का मंचन कर रहे निर्देशक हैं:\n“{l}”\nअभिनेता के लिए दो रंग-निर्देश (स्वर, हाव-भाव, गति या प्रकाश) सुझाइए और प्रत्येक का उद्देश्य बताइए।',
                    answer=f'उदाहरण: स्वर धीमा और काँपता हुआ; प्रकाश पात्र पर केंद्रित — उद्देश्य: {e}', type='short', marks=4,
                    markingKey='प्रत्येक रंग-निर्देश के लिए 2 अंक: 1 अंक व्यावहारिक, स्पष्ट निर्देश; 1 अंक अंश के भाव से जुड़ा उद्देश्य।')
    kit.add(key, 'C3', (2, 4), stage, 'short', None, 'dr_stage')


