def _cmp_pairs():
    out = []
    names = list(WORKS)
    for i, a in enumerate(names):
        for b in names[i + 1:]:
            for th_ in WORKS[a]:
                if th_ in WORKS[b]:
                    out.append((a, b, th_))
    return out


CMP_PAIRS = _cmp_pairs()


def g_cmpworks(kit, key, th):
    def essay(rng, slot):
        a, b, t = rng.choice(CMP_PAIRS)
        m = 8 if slot.d >= 4 else 6
        return dict(stem=f'{a} और {b} में ‘{t}’ विषय का चित्रण कैसे हुआ है? दोनों कृतियों से प्रमाण देते हुए समानताएँ और अंतर स्पष्ट कीजिए (150–200 शब्द)।',
                    answer=f'{a}: {WORKS[a][t]}। {b}: {WORKS[b][t]}। तुलना में विधा (नाटक/कहानी/दोहा) के अनुसार प्रस्तुति के अंतर पर भी ध्यान दें।',
                    type='long', marks=m, markingKey=f'{m} अंक: दोनों कृतियों की सही समझ और प्रमाण ({m // 2}), समानता-अंतर का स्पष्ट विश्लेषण ({m // 4}), तुलना की सुसंगत भाषा और निष्कर्ष ({m - m // 2 - m // 4})।')
    kit.add(key, 'C4', (3, 5), essay, 'long', None, 'cmp_essay')

    def point(rng, slot):
        a, b, t = rng.choice(CMP_PAIRS)
        return dict(stem=f'‘{t}’ — इस विषय पर {a} और {b} की तुलना के लिए एक-एक प्रमाण (घटना/पंक्ति) लिखिए और बताइए कि दोनों में क्या समानता है।',
                    answer=f'{a}: {WORKS[a][t]}। {b}: {WORKS[b][t]}। समानता: दोनों ‘{t}’ के माध्यम से मानवीय मूल्य/समाज पर टिप्पणी करती हैं।',
                    type='short', marks=3, markingKey='1 अंक प्रत्येक कृति से सही प्रमाण (2); 1 अंक समानता की स्पष्ट पहचान।')
    kit.add(key, 'C3', (2, 4), point, 'short', None, 'cmp_point')

    def which(rng, slot):
        a, b, t = rng.choice(CMP_PAIRS)
        w = rng.choice([a, b])
        others = [x for x in WORKS if x != w]
        return mcq(rng, f'‘{t}’ विषय से जुड़ा यह प्रसंग किस कृति का है?\n“{WORKS[w][t]}”', w, rng.sample(others, 3), f'यह प्रसंग {w} का है।')
    kit.add(key, ('C1', 'C2'), (1, 3), which, 'mcq', None, 'cmp_which')


