def g_visual(kit, key, th):
    def theme(rng, slot):
        d, t, cap, pts = rng.choice(VISUALS)
        return mcq(rng, f'मानक स्तर (SL) मौखिक परीक्षा का दृश्य उद्दीपन: {d}\nशीर्षक: {cap}\nयह उद्दीपन पाठ्यक्रम के किस विषय (theme) से सबसे सीधे जुड़ता है?', t,
                   rng.sample([x for x in IB_THEMES if x != t], 3), f'मुख्य संकेत: {pts} — इसलिए विषय ‘{t}’ है।')
    kit.add(key, 'C1', (1, 3), theme, 'mcq', None, 'vis_theme')

    def link(rng, slot):
        d, t, cap, pts = rng.choice(VISUALS)
        return dict(stem=f'दृश्य उद्दीपन: {d}\nशीर्षक: {cap}\nइस उद्दीपन को ‘{t}’ विषय से जोड़ते हुए बताइए कि आप अपनी प्रस्तुति में किन दो मुद्दों पर बात करेंगे और उन्हें किसी हिंदी-भाषी समाज से कैसे जोड़ेंगे।',
                    answer=f'संभावित मुद्दे: {pts}। हिंदी-भाषी संदर्भ: भारत/नेपाल/प्रवासी समुदाय से कोई ठोस उदाहरण।', type='short', marks=4,
                    markingKey='2 अंक: विषय से जुड़े दो प्रासंगिक मुद्दे; 1 अंक: शीर्षक/चित्र के विवरण का उपयोग; 1 अंक: हिंदी-भाषी समाज से ठोस सांस्कृतिक संबंध (मानदंड B1)।')
    kit.add(key, 'C3', (2, 4), link, 'short', None, 'vis_link')

    def caption(rng, slot):
        d, t, cap, pts = rng.choice(VISUALS)
        return dict(stem=f'दृश्य उद्दीपन: {d}\nशीर्षक: {cap}\nइस शीर्षक का चित्र से क्या संबंध है? शीर्षक प्रस्तुति की दिशा तय करने में कैसे मदद करता है?',
                    answer=f'शीर्षक ‘{cap}’ चित्र के मुख्य विचार ({pts}) की ओर संकेत करता है; इससे प्रस्तुति केवल वर्णन न रहकर विषय ‘{t}’ पर विचार बन जाती है।',
                    type='explain', marks=3, markingKey='1 अंक: शीर्षक और चित्र का संबंध; 1 अंक: विषय की पहचान; 1 अंक: प्रस्तुति की दिशा से जोड़ना।')
    kit.add(key, 'C2', (2, 4), caption, 'explain', None, 'vis_cap')

    def plan(rng, slot):
        d, t, cap, pts = rng.choice(VISUALS)
        m = 6 if slot.d >= 4 else 5
        return dict(stem=f'आपको 15 मिनट की तैयारी के लिए यह दृश्य उद्दीपन मिला है: {d} (शीर्षक: {cap})\n3–4 मिनट की प्रस्तुति की पूरी रूपरेखा बनाइए: आरंभ, वर्णन, विषय ‘{t}’ से संबंध, हिंदी-भाषी संस्कृति से तुलना, व्यक्तिगत विचार और समापन।',
                    answer=f'संभावित रूपरेखा: आकर्षक आरंभ; चित्र का संक्षिप्त वर्णन; मुद्दे — {pts}; हिंदी-भाषी समाज से उदाहरण; अपना मत; प्रश्न के साथ समापन।', type='explain', marks=m,
                    markingKey=f'{m} अंक: तार्किक संरचना (1), सटीक वर्णन (1), विषय से गहरा संबंध (1–2), सांस्कृतिक तुलना (1), व्यक्तिगत विचार और समापन (1)।')
    kit.add(key, 'C4', (3, 5), plan, 'explain', None, 'vis_plan')


