def g_extract(kit, key, th):
    def central(rng, slot):
        src, ex, idea, craft = rng.choice(EXTRACTS)
        others = [x[2] for x in EXTRACTS if x[1] != ex]
        return mcq(rng, f'उच्च स्तर (HL) मौखिक परीक्षा का अंश — {src}:\n“{ex}”\nप्रस्तुति के आरंभ में आप इस अंश का केंद्रीय विचार क्या बताएँगे?', idea,
                   rng.sample(others, 3), f'केंद्रीय विचार: {idea}।')
    kit.add(key, ('C1', 'C2'), (1, 3), central, 'mcq', None, 'ex_central')

    def craft_q(rng, slot):
        src, ex, idea, craft = rng.choice(EXTRACTS)
        return dict(stem=f'{src}:\n“{ex}”\nअपनी प्रस्तुति में इस अंश की कौन-सी दो शिल्पगत विशेषताओं पर बात करेंगे? प्रत्येक का केंद्रीय विचार से संबंध बताइए।',
                    answer=f'शिल्प: {craft}। केंद्रीय विचार ({idea}) को ये विशेषताएँ प्रभावी और यादगार बनाती हैं।', type='explain', marks=4,
                    markingKey='प्रत्येक विशेषता के लिए 2 अंक: 1 अंक सही पहचान, 1 अंक केंद्रीय विचार से संबंध (मानदंड B1 — अंश की समझ)।')
    kit.add(key, 'C2', (2, 4), craft_q, 'explain', None, 'ex_craft')

    def outline(rng, slot):
        src, ex, idea, craft = rng.choice(EXTRACTS)
        m = 6 if slot.d >= 4 else 5
        return dict(stem=f'आपको 20 मिनट की तैयारी के लिए यह अंश मिला है — {src}:\n“{ex}”\n3–4 मिनट की प्रस्तुति की रूपरेखा बनाइए: संदर्भ (कृति में अंश का स्थान), केंद्रीय विचार, शिल्प का विश्लेषण, कृति के बड़े विषय से संबंध और व्यक्तिगत प्रतिक्रिया।',
                    answer=f'संदर्भ; केंद्रीय विचार — {idea}; शिल्प — {craft}; कृति के व्यापक विषय से संबंध; व्यक्तिगत, तर्कसंगत प्रतिक्रिया।', type='explain', marks=m,
                    markingKey=f'{m} अंक: संदर्भ (1), केंद्रीय विचार (1), शिल्प-विश्लेषण उदाहरण सहित (1–2), कृति से संबंध (1), व्यक्तिगत प्रतिक्रिया (1)।')
    kit.add(key, 'C4', (3, 5), outline, 'explain', None, 'ex_outline')

    def opening(rng, slot):
        src, ex, idea, craft = rng.choice(EXTRACTS)
        return dict(stem=f'{src} के इस अंश पर अपनी प्रस्तुति का आरंभिक भाग (50–60 शब्द) लिखिए, जिसमें अंश का परिचय और आपका मुख्य विचार (थीसिस) हो:\n“{ex}”',
                    answer=f'नमूना: “आज मैं {src} के जिस अंश पर बोलूँगा/बोलूँगी, वह … मेरे विचार में इसका केंद्रीय संदेश है — {idea}…”', type='short', marks=3,
                    markingKey='1 अंक: अंश/कृति का परिचय; 1 अंक: स्पष्ट थीसिस; 1 अंक: प्रस्तुति के अनुरूप सहज, शुद्ध भाषा।')
    kit.add(key, 'C3', (2, 4), opening, 'short', None, 'ex_open')


