def g_conv(kit, key, th):
    def short(rng, slot):
        t, q, pts = rng.choice(CONV)
        return dict(stem=f'सामान्य वार्तालाप (विषय: {t}) — शिक्षक पूछते हैं: “{q}”\nइस प्रश्न का 40–60 शब्दों में सहज उत्तर लिखिए जिसमें एक कारण और एक उदाहरण हो।',
                    answer='संभावित बिंदु: ' + '; '.join(pts), type='explain', marks=3,
                    markingKey='1 अंक: प्रश्न का सीधा उत्तर; 1 अंक: कारण; 1 अंक: ठोस, व्यक्तिगत उदाहरण।')
    kit.add(key, 'C2', (1, 4), short, 'explain', None, 'conv_short')

    def extend(rng, slot):
        t, q, pts = rng.choice(CONV)
        return dict(stem=f'शिक्षक: “{q}”\nविद्यार्थी: “हाँ, मुझे लगता है।”\nयह उत्तर मौखिक परीक्षा के लिए बहुत छोटा है। इसे 80–100 शब्दों के विकसित उत्तर में बदलिए, जिसके अंत में शिक्षक से एक प्रति-प्रश्न हो।',
                    answer='अपेक्षित: स्पष्ट मत, ' + '; '.join(pts) + ' जैसे बिंदुओं का विकास, ठोस उदाहरण, और प्रति-प्रश्न (“आपका इस बारे में क्या विचार है?”)।', type='short', marks=4,
                    markingKey='1 अंक मत; 1 अंक विकसित तर्क; 1 अंक उदाहरण; 1 अंक संवाद को आगे बढ़ाने वाला प्रति-प्रश्न (मानदंड C)।')
    kit.add(key, 'C3', (2, 4), extend, 'short', None, 'conv_ext')

    def theme(rng, slot):
        t, q, pts = rng.choice(CONV)
        return mcq(rng, f'सामान्य वार्तालाप में शिक्षक का प्रश्न: “{q}”\nयह प्रश्न पाठ्यक्रम के किस विषय (theme) से जुड़ा है?', t,
                   rng.sample([x for x in IB_THEMES if x != t], 3), f'प्रश्न का मुख्य विचार ‘{t}’ विषय में आता है।')
    kit.add(key, 'C1', (1, 3), theme, 'mcq', None, 'conv_theme')

    def link(rng, slot):
        t, q, pts = rng.choice(CONV)
        return dict(stem=f'शिक्षक का प्रश्न: “{q}”\nइस प्रश्न के उत्तर को (क) अपने व्यक्तिगत अनुभव और (ख) किसी हिंदी-भाषी समाज (भारत, नेपाल, फ़िजी या प्रवासी समुदाय) के उदाहरण से कैसे जोड़ेंगे? दोनों संक्षेप में लिखिए।',
                    answer='संभावित बिंदु: ' + '; '.join(pts) + '। (क) अपने जीवन की कोई ठोस घटना; (ख) हिंदी-भाषी समाज का प्रासंगिक उदाहरण।', type='explain', marks=2,
                    markingKey='1 अंक: प्रासंगिक व्यक्तिगत अनुभव; 1 अंक: हिंदी-भाषी समाज का उपयुक्त उदाहरण।')
    kit.add(key, 'C2', (1, 4), link, 'explain', None, 'conv_link')

    def follow(rng, slot):
        t, q, pts = rng.choice(CONV)
        return dict(stem=f'आपकी प्रस्तुति के बाद शिक्षक बातचीत को ‘{t}’ विषय की ओर ले जाते हैं: “{q}”\nइस प्रश्न पर अपना मत, उसका विरोधी पक्ष और आपका अंतिम निष्कर्ष — तीनों को 120–150 शब्दों में लिखिए।',
                    answer='संभावित बिंदु: ' + '; '.join(pts) + '; विरोधी पक्ष को स्वीकार करके संतुलित निष्कर्ष।', type='explain', marks=6,
                    markingKey='6 अंक: स्पष्ट मत (1), विकसित तर्क और उदाहरण (2), विरोधी पक्ष (1), संतुलित निष्कर्ष (1), सहज, शुद्ध भाषा (1)।')
    kit.add(key, 'C4', (3, 5), follow, 'explain', None, 'conv_follow')


