def g_tt12(kit, key, th):
    def pick(rng, slot):
        s, tt, p = rng.choice(TT_SITU12)
        X = TT[tt]
        pool = [v['name'] for k, v in TT.items() if v['grp'] != X['grp']]
        return mcq(rng, f'पेपर 1 का कार्य: {s}\nइस कार्य के लिए सबसे उपयुक्त पाठ-प्रकार कौन-सा होगा?', X['name'], rng.sample(pool, 3),
                   f'उद्देश्य ({p}) और पाठक ({X["aud"]}) के कारण {X["name"]} सबसे उपयुक्त है।')
    kit.add(key, 'C1', (1, 3), pick, 'mcq', None, 'tt12_pick')

    def purpose(rng, slot):
        s, tt, p = rng.choice(TT_SITU12)
        others = [x[2] for x in TT_SITU12 if x[1] != tt]
        return mcq(rng, f'कार्य: {s}\nइस कार्य का मुख्य उद्देश्य क्या है?', p, rng.sample(others, 3), f'मुख्य उद्देश्य: {p}; इसलिए पाठ-प्रकार {TT[tt]["name"]}।')
    kit.add(key, 'C2', (2, 3), purpose, 'mcq', None, 'tt12_purpose')

    def three(rng, slot):
        rows = []
        for r in rng.sample(TT_SITU12, len(TT_SITU12)):
            if all(TT[r[1]]['grp'] != TT[x[1]]['grp'] or r[1] != x[1] for x in rows) and r[1] not in [x[1] for x in rows]:
                rows.append(r)
            if len(rows) == 3:
                break
        lst = '\n'.join(f'({"कखग"[i]}) {r[0]}' for i, r in enumerate(rows))
        ans = ' '.join(f'({"कखग"[i]}) {TT[r[1]]["name"]} — पाठक: {TT[r[1]]["aud"]}; उद्देश्य: {r[2]}।' for i, r in enumerate(rows))
        return dict(stem=f'पेपर 1 में आपको इन तीन कार्यों में से एक चुनना है:\n{lst}\nप्रत्येक कार्य का पाठ-प्रकार, लक्षित पाठक और उद्देश्य बताइए। फिर लिखिए कि आप कौन-सा कार्य चुनेंगे और क्यों।',
                    answer=ans + ' चुनाव का कारण: पाठ-प्रकार की परंपराओं पर पकड़, विषय की जानकारी और उपयुक्त शब्दावली।', type='short', marks=5,
                    markingKey='3 अंक: तीनों कार्यों के पाठ-प्रकार, पाठक और उद्देश्य की सही पहचान (प्रत्येक कार्य 1); 2 अंक: चुनाव का तर्कसंगत कारण (परंपराओं का ज्ञान, विषय-ज्ञान, शब्दावली)।')
    kit.add(key, 'C3', (3, 5), three, 'short', None, 'tt12_three')

    def plan(rng, slot):
        s, tt, p = rng.choice(TT_SITU12)
        X = TT[tt]
        return dict(stem=f'कार्य: {s}\nलिखना शुरू करने से पहले इस कार्य का विश्लेषण कीजिए: (क) पाठ-प्रकार, (ख) लक्षित पाठक, (ग) उद्देश्य, (घ) रजिस्टर और (ङ) पाठ-प्रकार की दो परंपराएँ।',
                    answer=f'(क) {X["name"]}; (ख) {X["aud"]}; (ग) {p}; (घ) {X["reg"]}; (ङ) {X["conv"][0]}; {X["conv"][1]}।', type='explain', marks=5,
                    markingKey='पाँचों भागों के लिए 1-1 अंक; मिलते-जुलते उचित उत्तर स्वीकार्य।')
    kit.add(key, 'C2', (2, 4), plan, 'explain', None, 'tt12_plan')

    def wrong(rng, slot):
        s, tt, p = rng.choice(TT_SITU12)
        X = TT[tt]
        Y = TT[rng.choice([k for k, v in TT.items() if v['grp'] != X['grp']])]
        return dict(stem=f'कार्य: {s}\nएक विद्यार्थी ने इस कार्य के लिए {Y["name"]} लिखा। परीक्षक मानदंड C में उसके अंक क्यों काटेगा? सही पाठ-प्रकार और उसका कारण बताइए।',
                    answer=f'सही पाठ-प्रकार {X["name"]} है, क्योंकि उद्देश्य है — {p}; पाठक: {X["aud"]}। {Y["name"]} का रजिस्टर ({Y["reg"]}) और परंपराएँ इस उद्देश्य और पाठक से मेल नहीं खातीं।',
                    type='short', marks=3, markingKey='1 अंक: सही पाठ-प्रकार; 1 अंक: उद्देश्य/पाठक के आधार पर कारण; 1 अंक: मानदंड C (अवधारणात्मक समझ) से संबंध।')
    kit.add(key, 'C3', (2, 4), wrong, 'short', None, 'tt12_wrong')


