def title_mcq(kit, key, th, which, style):
    """Gist inference: choose the best title for a text/transcript (distractors: sibling texts first)."""
    TX = th.get(which, [])
    if not TX:
        return
    pool_all = [t['title'] for k in sorted(TH) for w in ((which,) if which == 'audio' else ('texts', 'texts2')) for t in TH[k].get(w, [])]

    def fn(rng, slot):
        t = rng.choice(TX)
        sib = [x['title'] for x in TX if x is not t]
        far = [x for x in pool_all if x != t['title'] and x not in sib]
        wrong = sib[:3] + rng.sample(far, 3 - len(sib[:3]))
        if which == 'audio':
            lead = f'नीचे एक {t["kind"]} का प्रतिलेख है (परीक्षा में आप इसे सुनेंगे)। ध्यान से पढ़िए।'
            q = 'इस श्रव्य अंश के लिए सबसे उपयुक्त शीर्षक कौन-सा है?'
        else:
            lead = f'नीचे {H.given(t["kind"])} {t["kind"]} पढ़िए (शीर्षक हटा दिया गया है)।'
            q = 'पाठ के मुख्य विचार के आधार पर इसके लिए सबसे उपयुक्त शीर्षक कौन-सा है?'
        return mcq(rng, f'{lead}\n\n{t["body"]}\n\n{q}', t['title'], wrong, f'पूरा पाठ इसी केंद्रीय विषय पर है: “{t["title"]}”।')
    kit.add(key, 'C3', (2, 4), fn, 'mcq', style, 'tx_title')


