    if _ch in READ_CH_G12:
        title_mcq(KIT, _key, TH[_ch], 'texts', 'p2r')
        title_mcq(KIT, _key, TH[_ch], 'texts2', 'p2r')
        KIT.vocab(_key, TH[_ch], ('c3',))
    if _ch in LISTEN_CH_G12:
        title_mcq(KIT, _key, TH[_ch], 'audio', 'p2l')
